names=list(cols)
def fit(ns):
    A=np.column_stack([cols[n] for n in ns])
    c=np.linalg.lstsq(A,dv_dt,rcond=None)[0]
    r=A@c-dv_dt
    return c, np.mean(r**2)/np.var(dv_dt)
